const CONTACT={email:"",github:"https://github.com/sumitparmartech",x:"https://x.com/sumitparmar_ai",linkedin:"https://www.linkedin.com/in/sumitparmar-ai/",whatsapp:"https://wa.me/918487027268?text=Hi%20Sumit%2C%20I%20saw%20your%20portfolio%20and%20would%20like%20to%20connect.",phone:"+91 84870 27268",resume:""};
const PROJECTS=[
 {id:"knowledge-layer",fig:null,area:"Context engineering · Agents",status:"In progress",title:"Enterprise Brain",
  sum:"A company brain that connects mail, tasks and code, answers with sources, and lets agents act on what it finds.",
  role:"Core engineer",stack:["Python","FastAPI","HydraDB","PostgreSQL","Knowledge graph","MCP"],
  steps:[["Problem","Company knowledge is scattered across mail, tasks and code. People ask about status, owners and blockers, and nobody has the full picture in one place."],
   ["Context","Gmail, ClickUp and GitHub to start, with more tools to be added. Each source has its own structure, rhythm and permissions."],
   ["Approach","Everything becomes searchable memory. A knowledge graph links what belongs together, so a task leads to the mail about it and the PR that shipped it. Agents use MCP tools to act on the answer."],
   ["Decision","Evaluated pgvector against HydraDB and chose HydraDB as the base, adding graph structure only where the questions need it."],
   ["Outcome","A context layer that works like a product manager next to the developers: it knows the status, finds the trail and moves the work forward."]],
  learn:"Answers are good. Answers with the trail behind them are what people trust."},
 {id:"call-analysis",fig:"call",area:"LLM pipelines",status:"Live",title:"LLM call analysis",
  sum:"Pipelines that turn hours of recorded calls into structured insight for enterprise and real estate teams.",
  role:"Built end to end",stack:["Speech to text","LLM","Structured outputs","FastAPI","PostgreSQL","RBAC"],
  steps:[["Problem","Teams record hundreds of calls and nobody has time to listen. Intent, objections and follow ups stay buried in audio."],
   ["Context","Long, noisy, multi-speaker audio, different classification needs per client, and data that has to stay scoped by role."],
   ["Approach","Transcription, then LLM analysis against fixed output schemas, call classification, and real-time data pipelines into role-scoped dashboards."],
   ["Decision","Budgeted context and output tokens per call, so quality stayed high while cost stayed predictable."],
   ["Outcome","Running for client teams, with classification improved through prompt and schema iteration."]],
  learn:"Schemas first. A model that answers in a fixed shape is a model you can test."},
 {id:"voice-ai",fig:"voice",area:"Voice AI",status:"Live",title:"Voice AI under real load",
  sum:"Speech to text and text to speech features that hold up when many people use them at once.",
  role:"Backend and performance",stack:["Python","FastAPI","STT","TTS","Async jobs","Load testing"],
  steps:[["Problem","Voice features that feel fine for one user can fall apart when many people use them at once."],
   ["Context","Batch speech to text through an external API, long audio files, and users waiting on the result."],
   ["Approach","Load tested the pipeline, found the bottleneck in how batch jobs were handled, and moved long work to asynchronous processing with live status in the UI."],
   ["Decision","Treat long transcription as a job, not a request."],
   ["Outcome","Validated at around 50 concurrent users, with a predictable experience for long files."]],
  learn:"Load test before your users do it for you."},
 {id:"document-ai",fig:"doc",area:"Document AI",status:"Live",title:"Document AI and OCR",
  sum:"Extraction from scans, photos and PDFs behind a multi-provider model layer.",
  role:"Built and debugged",stack:["Python","FastAPI","LiteLLM","Gemini","OCR"],
  steps:[["Problem","Documents arrive in every shape. Extraction has to be accurate no matter which model reads them."],
   ["Context","Several model providers behind one gateway, each with its own naming and quirks."],
   ["Approach","An OCR pipeline behind a model layer, so the right model can be chosen per document type."],
   ["Decision","Found requests silently routed to the wrong provider model and added an explicit model map, so every OCR call reaches the intended model."],
   ["Outcome","Reliable extraction where model choice is set by config, not by luck."]],
  learn:"Always check which model actually served the request."},
 {id:"model-gateway",fig:"route",area:"Model routing · Cost",status:"Live",title:"Multi-model routing",
  sum:"Making sure every request on a many-model platform reaches the right model at the right price.",
  role:"Platform engineering",stack:["LiteLLM","Python","FastAPI","Next.js"],
  steps:[["Problem","A platform that offers many LLMs needs routing users can trust, and spend the business can predict."],
   ["Context","A shared model registry used by both the backend and the product UI."],
   ["Approach","Added guards before model resolution, cleaned the registry, and removed unsupported models from backend and frontend together."],
   ["Decision","Choose models per task on quality, latency and price, and keep routing explicit and testable."],
   ["Outcome","Fewer silent failures, including a chat quality issue where the system prompt was being sent as a user message."]],
  learn:"Log what actually reaches the model. Roles included."},
 {id:"automation-rbac",fig:"rbac",area:"Automation · Access",status:"Live",title:"AI automation with access control",
  sum:"Multi-user AI workflows that respect who is allowed to see and run what.",
  role:"Full stack",stack:["Workflow orchestration","RBAC","FastAPI","Next.js","PostgreSQL"],
  steps:[["Problem","AI workflows touch sensitive client data, and different people should see different things."],
   ["Context","Teams, groups and roles across a product with dashboards, automations and APIs."],
   ["Approach","Route protection, conditional UI and role dashboards on the frontend. Auth middleware, a permission matrix and group-scoped queries on the backend."],
   ["Decision","Enforce permissions at the query level, not only in the interface."],
   ["Outcome","Automations teams can share without leaking data across roles."]],
  learn:"If the UI is the only guard, there is no guard."},
 {id:"finance-data",fig:"fin",area:"Data · Finance",status:"Live",title:"Plain English over accounting data",
  sum:"Answers from accounting data without writing SQL, checked against how Indian businesses actually close their books.",
  role:"Backend and validation",stack:["PostgreSQL","AWS RDS","SQL templates","Python"],
  steps:[["Problem","Business owners want answers from their accounting data without learning SQL."],
   ["Context","A library of SQL templates over real accounting data on PostgreSQL."],
   ["Approach","Validated templates against real data, with a structured review prompt for pre-production checks."],
   ["Decision","Fixed date logic that used the calendar year where finance needs the April to March financial year."],
   ["Outcome","Reports that match the numbers accountants expect."]],
  learn:"The SQL can run perfectly and still be wrong. Test the business rules."}
];
