function split(el){let i=0;const walk=n=>{[...n.childNodes].forEach(c=>{if(c.nodeType===3){const f=document.createDocumentFragment();c.textContent.split(/(\s+)/).forEach(p=>{if(!p)return;if(/^\s+$/.test(p)){f.appendChild(document.createTextNode(' '));return;}const w=document.createElement('span');w.className='w';const s=document.createElement('span');s.textContent=p;s.style.setProperty('--i',i++);w.appendChild(s);f.appendChild(w);});c.replaceWith(f);}else if(c.nodeType===1){if(c.classList.contains('o')){const w=document.createElement('span');w.className='w o';c.childNodes.length;const words=c.textContent.split(' ');c.replaceWith(...words.flatMap((wd,k)=>{const ww=document.createElement('span');ww.className='w o';const s=document.createElement('span');s.textContent=wd;s.style.setProperty('--i',i++);ww.appendChild(s);return k?[document.createTextNode(' '),ww]:[ww];}));}else walk(c);}});};walk(el);}
