   if(lens>.02){const dx=d.x-mx,dy=d.y-my,dd=Math.hypot(dx,dy);if(dd<LR*1.25&&dd>0){const f=(1-dd/(LR*1.25))*lens;tx+=dx/dd*f*LR*.35;ty+=dy/dd*f*LR*.35;}}
